61	  不改变超限或恢复状态。alerts 按规则和日期展示消耗或不可判定原因、各次
62	  告警的标识、检测状态、确认状态及触发/恢复/确认的处理顺序;省略日期范围
63	  时展示有告警记录的全部日期。导入不自动评估,补导后需显式重评。
64	
65	CSV 格式:
66	  表头: ${CSV_HEADER}
67	  device   设备标识(区分大小写,首尾空白忽略,去空白后不能为空)
68	  time     秒精度 ISO8601,带 Z 或数字时区偏移;必须是真实日期
69	  reading  累计电表读数(kWh,非负,最多三位小数;可超出 Number 安全整数
70	           范围,任意大的十进制值都精确保存,如 9007199254740.991)
71	  支持标准双引号字段与 "" 转义;同一设备同一时刻(按实际时刻判定)
72	  重复且数值相同记为重复跳过,数值不同视为冲突并拒绝整批。
73	
74	数值精度:
75	  读数与阈值以毫千瓦时 BigInt 运算,解析、求差、分摊、汇总、比较、保存
76	  和显示全程精确,输出固定三位小数,不使用科学计数法。
77	  兼容旧版 readings.json / alerts.json 中以 JSON 数值保存的安全整数
78	  读数与阈值,无需手工转换;新版以十进制字符串保存。数值型毫千瓦时若
79	  已超出安全整数范围(精度已丢失)按损坏数据拒绝,不猜测原值。
80	
81	数据位置:
82	  $METERWATCH_DATA_DIR/readings.json(默认 ~/.meterwatch/readings.json)
83	  $METERWATCH_DATA_DIR/alerts.json(告警规则与历史,与读数文件相互独立)
84	
85	退出码: 0 成功;1 数据或读写错误;2 参数错误`;
86	
87	function usageError(message: string): number {
88	  console.error(`${name}: ${message}`);
89	  console.error(`用法见 'node app.ts --help'`);
90	  return 2;
91	}
92	
93	interface ParsedOptions {
94	  devices: string[];
95	  from?: number;
96	  to?: number;
97	}
98	
99	/** 解析 --device/--from/--to 选项;出错返回错误消息字符串。 */
100	function parseOptions(rest: string[]): ParsedOptions | string {
101	  const devices: string[] = [];
102	  let from: number | undefined;
103	  let to: number | undefined;
104	  for (let i = 0; i < rest.length; i++) {
105	    let opt = rest[i];
106	    let value: string | undefined;
107	    const eq = opt.indexOf('=');
108	    if (opt.startsWith('--') && eq !== -1) {
109	      value = opt.slice(eq + 1);
110	      opt = opt.slice(0, eq);
111	    } else if (opt.startsWith('--')) {
112	      value = rest[i + 1];
113	      if (value === undefined) return `选项 '${opt}' 缺少值`;
114	      i++;
115	    } else {
116	      return `无法识别的参数 '${opt}'`;
117	    }
118	    if (opt === '--device') {
119	      if (value.trim() === '') return "'--device' 的值不能为空";
120	      devices.push(value);
121	    } else if (opt === '--from' || opt === '--to') {
122	      const ts = parseIso8601(value.trim());
123	      if (ts === null) {
124	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
125	      }
126	      if (opt === '--from') from = ts;
127	      else to = ts;
128	    } else {
129	      return `无法识别的选项 '${opt}'`;
130	    }
131	  }
132	  return { devices, from, to };
133	}
134	
135	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
136	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
137	  const out = new Map<string, string[]>();
138	  for (let i = 0; i < rest.length; i++) {
139	    let opt = rest[i];
140	    let value: string | undefined;
141	    const eq = opt.indexOf('=');
142	    if (opt.startsWith('--') && eq !== -1) {
143	      value = opt.slice(eq + 1);
144	      opt = opt.slice(0, eq);
145	    } else if (opt.startsWith('--')) {
146	      value = rest[i + 1];
147	      if (value === undefined) return `选项 '${opt}' 缺少值`;
148	      i++;
149	    } else {
150	      return `无法识别的参数 '${opt}'`;
151	    }
152	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
153	    const list = out.get(opt);
154	    if (list) list.push(value);
155	    else out.set(opt, [value]);
156	  }
157	  return out;
158	}
159	
160	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
161	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
162	  const list = flags.get(name);
163	  if (!list || list.length !== 1) return null;
164	  return list[0];
165	}
166	
167	/** 解析 YYYY-MM-DD 日期选项;无效时返回错误消息字符串。 */
168	function dateFlag(value: string, label: string): number | string {
169	  const ts = parseUtcDate(value.trim());
170	  if (ts === null) return `${label}无效: '${value.trim()}'(需 YYYY-MM-DD 的真实 UTC 日期)`;
171	  return ts;
172	}
173	
174	function cmdRule(rest: string[]): number {
175	  const [sub, ...subrest] = rest;
176	  if (sub === 'list') {
177	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
178	    return cmdRuleList();
179	  }
180	  if (sub === 'create') {
181	    const flags = parseFlags(subrest, ['--id', '--device', '--threshold']);
182	    if (typeof flags === 'string') return usageError(flags);
183	    const idRaw = oneFlag(flags, '--id');
184	    const deviceRaw = oneFlag(flags, '--device');
185	    const thresholdRaw = oneFlag(flags, '--threshold');
186	    if (idRaw === null || deviceRaw === null || thresholdRaw === null) {
187	      return usageError("'rule create' 需要 --id、--device、--threshold 各恰好一个");
188	    }
189	    const id = idRaw.trim();
190	    if (id === '') return usageError('规则标识不能为空');
191	    const device = deviceRaw.trim();
192	    if (device === '') return usageError("'--device' 的值不能为空");
193	    const thresholdMilli = parseKwh(thresholdRaw.trim());
194	    if (thresholdMilli === null) {
195	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
196	    }
197	    return cmdRuleCreate({ id, device, thresholdMilli });
198	  }
199	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
200	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
201	}
202	
203	function cmdEvaluateEntry(rest: string[]): number {
204	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
205	  if (typeof flags === 'string') return usageError(flags);
206	  const ruleRaw = oneFlag(flags, '--rule');
207	  const fromRaw = oneFlag(flags, '--from');
208	  const toRaw = oneFlag(flags, '--to');
209	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
210	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
211	  }
212	  const ruleId = ruleRaw.trim();
213	  if (ruleId === '') return usageError('规则标识不能为空');
214	  const from = dateFlag(fromRaw, '起始日期');
215	  if (typeof from === 'string') return usageError(from);
216	  const to = dateFlag(toRaw, '结束日期');
217	  if (typeof to === 'string') return usageError(to);
218	  if (from >= to) return usageError('评估起日必须早于止日(--from < --to)');
219	  return cmdEvaluate({ ruleId, from, to });
220	}
221	
222	function cmdAlertsEntry(rest: string[]): number {
223	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
224	  if (typeof flags === 'string') return usageError(flags);
225	  const ruleRaw = oneFlag(flags, '--rule');
226	  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
227	  const ruleId = ruleRaw.trim();
228	  if (ruleId === '') return usageError('规则标识不能为空');
229	  const fromList = flags.get('--from');
230	  const toList = flags.get('--to');
231	  if ((fromList !== undefined) !== (toList !== undefined)) {
232	    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
233	  }
234	  let from: number | undefined;
235	  let to: number | undefined;
236	  if (fromList !== undefined) {
237	    const fromRaw = oneFlag(flags, '--from');
238	    const toRaw = oneFlag(flags, '--to');
239	    if (fromRaw === null || toRaw === null) {
240	      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
241	    }
242	    const fromParsed = dateFlag(fromRaw, '起始日期');
243	    if (typeof fromParsed === 'string') return usageError(fromParsed);
244	    const toParsed = dateFlag(toRaw, '结束日期');
245	    if (typeof toParsed === 'string') return usageError(toParsed);
246	    if (fromParsed >= toParsed) return usageError('查询起日必须早于止日(--from < --to)');
247	    from = fromParsed;
248	    to = toParsed;
249	  }
250	  return cmdAlerts({ ruleId, from, to });
251	}
252	
253	function main(args: string[]): number {
254	  if (args.length === 0) {
255	    console.log(help);
256	    return 0;
257	  }
258	  const [cmd, ...rest] = args;
259	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
260	    console.log(help);
261	    return 0;
262	  }
263	
264	  if (cmd === 'import') {
265	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
266	    return cmdImport(rest[0]);
267	  }
268	
269	  if (cmd === 'readings') {
270	    const parsed = parseOptions(rest);
271	    if (typeof parsed === 'string') return usageError(parsed);
272	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
273	      return usageError('查询起点必须早于终点(--from < --to)');
274	    }
275	    return cmdReadings(parsed);
276	  }
277	
278	  if (cmd === 'daily') {
279	    const parsed = parseOptions(rest);
280	    if (typeof parsed === 'string') return usageError(parsed);
281	    if (parsed.from === undefined || parsed.to === undefined) {
282	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
283	    }
284	    if (parsed.from >= parsed.to) {
285	      return usageError('查询起点必须早于终点(--from < --to)');
286	    }
287	    return cmdDaily({ devices: parsed.devices, from: parsed.from, to: parsed.to });
288	  }
289	
290	  if (cmd === 'rule') return cmdRule(rest);
291	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
292	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
293	
294	  if (cmd === 'ack') {
295	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
296	    const alertId = rest[0].trim();
297	    if (alertId === '') return usageError('告警标识不能为空');
298	    return cmdAck(alertId);
299	  }
300	
301	  return usageError(`无法识别的参数 '${cmd}'`);
302	}
303	
304	process.exitCode = main(process.argv.slice(2));
305

