    let version: GroupVersion | null = null;
    for (const v of versions) { if (v.ts <= p) version = v; else break; }
    periods.push({ start: p, end: q, members: version ? version.members : null });
    if (!version) { unknown += q - p; continue; }

    // 切点:成员读数时刻落在 (p, q) 内
    const cuts = new Set<number>();
    for (const m of version.members) {
      const series = seriesByDevice.get(m);
      if (!series) continue;
      for (const r of series) if (r.ts > p && r.ts < q) cuts.add(r.ts);
    }
    const points = [p, ...[...cuts].sort((a, b) => a - b), q];

    for (let j = 0; j + 1 < points.length; j++) {
      const s = points[j], e = points[j + 1];
      let sliceAnomaly = false, sliceUnknown = false, sliceConsumption = 0n;
      for (const m of version.members) {
        const series = seriesByDevice.get(m);
        const iv = series ? intervalAt(series, s) : null;
        if (!iv) { sliceUnknown = true; continue; }
        const diff = iv.b.milli - iv.a.milli;
        if (diff < 0n) { sliceAnomaly = true; continue; }
        const duration = BigInt(iv.b.ts - iv.a.ts);
        const cum = (t: number): bigint => (diff * BigInt(t - iv.a.ts)) / duration;
        sliceConsumption += cum(e) - cum(s);
      }
      if (sliceAnomaly) anomaly += e - s;
      else if (sliceUnknown) unknown += e - s;
      else { valid += e - s; consumption += sliceConsumption; }
    }
  }
  return { valid, anomaly, unknown, consumption, periods };
}
```

