export function cmdGroupConfig(opts: { id: string; at: number; devices: string[] }): number {
  const statePath = groupFilePath();
  let state: GroupState;
  let known: Set<string>;
  try {
    state = loadGroupState(statePath);
    known = new Set(loadStore(dataFilePath()).map((r) => r.device));
  } catch (e) {
    if (e instanceof StoreError) { err(e.message); return 1; }
    throw e;
  }

  const members = [...new Set(opts.devices)].sort(compareStrings);
  if (members.length === 0) { err(`group '${opts.id}': member set must not be empty`); return 1; }
  const unknownDevices = members.filter((d) => !known.has(d));
  if (unknownDevices.length > 0) {
    err(`unknown device(s): ${unknownDevices.join(', ')}: no stored readings; import readings before configuring a group`);
    return 1;
  }

  const group = state.groups.find((g) => g.id === opts.id);
  const membersText = members.join(', ');
  if (!group) {
    state.groups.push({ id: opts.id, versions: [{ ts: opts.at, members }] });
    try { saveGroupState(statePath, state); } catch ...
    console.log(`group '${opts.id}' created: version 1 effective from ${formatIsoUtc(opts.at)}  members: ${membersText}`);
    return 0;
  }
  const existing = group.versions.find((v) => v.ts === opts.at);
  if (existing) {
    if (arraysEqual(existing.members, members)) {
      console.log(`group '${opts.id}' already has an identical version effective from ${formatIsoUtc(opts.at)} (members: ${membersText}); unchanged`);
      return 0;
    }
    err(`group '${opts.id}' already has a version effective from ${formatIsoUtc(opts.at)} with different members (stored: ${existing.members.join(', ')}; got: ${membersText}); conflict`);
    return 1;
  }
  group.versions.push({ ts: opts.at, members });
  group.versions.sort((a, b) => a.ts - b.ts);
  try { saveGroupState(...); } catch ...
  const idx = group.versions.findIndex((v) => v.ts === opts.at);
  console.log(`group '${opts.id}' version ${idx + 1} added: effective from ${formatIsoUtc(opts.at)}  members: ${membersText}`);
  return 0;
}
