export function cmdGroupDaily(opts: { id: string; from: number; to: number }): number {
  let state: GroupState;
  let all: Reading[];
  try {
    state = loadGroupState(groupFilePath());
    all = loadStore(dataFilePath());
  } catch ...
  const group = state.groups.find((g) => g.id === opts.id);
  if (!group) { err(`unknown group '${opts.id}'`); return 1; }

  const needed = new Set<string>();
  for (const v of group.versions) for (const m of v.members) needed.add(m);
  const seriesByDevice = new Map<string, Reading[]>();
  for (const r of all) {
    if (!needed.has(r.device)) continue;
    const list = seriesByDevice.get(r.device);
    if (list) list.push(r); else seriesByDevice.set(r.device, [r]);
  }
  for (const [device, list] of seriesByDevice) {
    list.sort((a, b) => a.ts - b.ts);
    for (let i = 1; i < list.length; i++) {
      if (list[i].ts === list[i - 1].ts) {
        err(`storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(list[i].ts)}`);
        return 1;
      }
    }
  }

  console.log(`group: ${group.id}`);
  let total = 0n; let computedDays = 0; let days = 0; let incomplete = false;
  for (let dayStart = Math.floor(opts.from / DAY_SECONDS) * DAY_SECONDS; dayStart < opts.to; dayStart += DAY_SECONDS) {
    const segStart = Math.max(dayStart, opts.from);
    const segEnd = Math.min(dayStart + DAY_SECONDS, opts.to);
    const stats = computeGroupDay(group.versions, seriesByDevice, segStart, segEnd);
    days++;
    const date = formatIsoUtc(dayStart).slice(0, 10);
    const dayIncomplete = stats.anomaly > 0 || stats.unknown > 0;
    if (dayIncomplete) incomplete = true;
    let consumption: string;
    if (stats.valid > 0) {
      consumption = `consumption=${formatKwh(stats.consumption)} kWh (estimate)`;
      total += stats.consumption;
      computedDays++;
    } else {
      consumption = 'consumption=n/a (no valid coverage)';
    }
    let line = `  ${date}  ${consumption}  valid=${stats.valid}s  anomaly=${stats.anomaly}s  unknown=${stats.unknown}s`;
    if (dayIncomplete) line += '  INCOMPLETE';
    console.log(line);
    for (const period of stats.periods) {
      const who = period.members === null ? '(none — before first version)' : period.members.join(', ');
      console.log(`    members: ${who}  (${formatIsoUtc(period.start)}..${formatIsoUtc(period.end)})`);
    }
  }
  const totalText = computedDays > 0 ? `total consumption=${formatKwh(total)} kWh (estimate)` : 'total consumption=n/a (no valid coverage)';
  const status = incomplete ? 'status=INCOMPLETE (unknown or anomaly coverage present)' : 'status=complete';
  console.log(`  summary: group=${group.id}  computed=${computedDays}/${days} day(s)  ${totalText}  ${status}`);
  return 0;
}
